with exploded as (select id, log_ts, level, latency_ms, status_code, k, attr_value from app_logs lateral view explode(context) t as k, attr_value), flagged as (select *, case when lag(log_ts) over (partition by level order by log_ts, id, k) is null or log_ts > lag(log_ts) over (partition by level order by log_ts, id, k) + interval 20 minutes then 1 else 0 end as new_group_flag from exploded), islands as (select *, sum(new_group_flag) over (partition by level order by log_ts, id, k rows between unbounded preceding and current row) as burst_id from flagged), deduped as (select *, row_number() over (partition by level order by burst_id, id, k) as rank_in_group from islands qualify rank_in_group = 1), with_prev as (select *, lag(log_ts) over (partition by level order by log_ts, id, k) as prev_log_ts from deduped), with_gaps as (select *, case when prev_log_ts is null or log_ts > prev_log_ts + interval 15 minutes then 1 else 0 end as new_group_flag_2 from with_prev), sessionized as (select *, sum(new_group_flag_2) over (partition by level order by log_ts, id, k rows between unbounded preceding and current row) as session_id from with_gaps) select date_trunc('hour', log_ts) as hour_window, date_trunc('year', prev_log_ts) as year_start, date_trunc('day', log_ts) as activity_day, sum(status_code) as total_status_code, round(sum(new_group_flag) / nullif(count(case when k = 'region' then 1 end), 0), 2) as new_group_flag_per_region, count(case when k = 'version' then 1 end) as version_count, grouping(date_trunc('hour', log_ts)) as grouping_level from sessionized group by grouping sets ((date_trunc('hour', log_ts), date_trunc('year', prev_log_ts), date_trunc('day', log_ts)), (date_trunc('hour', log_ts), date_trunc('year', prev_log_ts)), ()) having count(case when k = 'version' then 1 end) > 1;
